using System;
using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "PlasmaWhipOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/PlasmaWhipOmenData")]
public class PlasmaWhipOmenData : OnNewRuneOmenData
{
	[SerializeField]
	private OmenLogicActionFace omenLogicActionFace;

	[NonSerialized]
	private Action omenAction;

	[NonSerialized]
	private Rune oldRuneLoseRuneLeftmost;

	[NonSerialized]
	private Rune oldRuneLoseRuneRightmost;

	private RunesPanelInitializer runesPanelInitializer => runesPanelGameObjectReference.value.GetComponent<RunesPanelInitializer>();

	public override void Initialize(OmenInstance omenInstance)
	{
		int leftmostVirtueIndex = GetLeftmostVirtueIndex();
		if (leftmostVirtueIndex != -1)
		{
			Rune rune = runesPanelInitializer.Runes[leftmostVirtueIndex];
			oldRuneLoseRuneLeftmost = new Rune(rune.FaceName, rune.ActionValue, rune.BattleAction, rune.index);
			runesPanelInitializer.ReplaceRuneWithNewRune(null, 0, leftmostVirtueIndex);
		}
		int emptyRightmostIndex = GetEmptyRightmostIndex();
		if (emptyRightmostIndex != -1)
		{
			Rune rune2 = runesPanelInitializer.Runes[emptyRightmostIndex];
			oldRuneLoseRuneRightmost = new Rune(rune2.FaceName, rune2.ActionValue, rune2.BattleAction, rune2.index);
			runesPanelInitializer.AddNewRune(oldRuneLoseRuneLeftmost.BattleAction, oldRuneLoseRuneLeftmost.ActionValue, emptyRightmostIndex);
		}
		base.Initialize(omenInstance);
		omenAction = delegate
		{
			omenLogicActionFace.ActivateOmen();
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerPlayVirtueOmenAction.Add(omenAction);
	}

	private int GetLeftmostVirtueIndex()
	{
		Rune[] runes = runesPanelInitializer.Runes;
		for (int num = runes.Length - 1; num >= 0; num--)
		{
			if (runes[num].BattleAction != null)
			{
				return num;
			}
		}
		return -1;
	}

	private int GetEmptyRightmostIndex()
	{
		Rune[] runes = runesPanelInitializer.Runes;
		for (int i = 0; i < runes.Length; i++)
		{
			if (runes[i].BattleAction == null)
			{
				return i;
			}
		}
		return -1;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerPlayVirtueOmenAction.Remove(omenAction);
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		string text = Smart.Format(base.localizationManager.GetLocalizedWheneverPlayAVirtue(), omenLogicActionFace.GetActionDescription());
		return text + "\n" + GetOmenRawLocalizedDescription() + "\n" + base.OmenConvertedDescription();
	}
}
